#include "TestRecipes.h"
#include "DetailProcessing.h"
#include "NoiseEstimation.h"
#include "WorkingColorSpace.h"
#include <QCoreApplication>
#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <opencv2/imgproc.hpp>
#include <array>
#include <chrono>
#include <cmath>
#include <iostream>
#include <stdexcept>

namespace {
void require(bool ok,const char *message) {if(!ok) throw std::runtime_error(message);}
}

int main(int argc,char **argv)
{
    QCoreApplication app(argc,argv);
    try {
        require(argc==3,"Usage: iprNoiseSingleAudit output-json input-raw");
        cv::setNumThreads(4);const auto args=app.arguments();
        const auto loaded=TestRecipes::load(args[2]);const auto settings=TestRecipes::neutral(loaded);
        const auto working=ImageEditor::renderLinear(loaded.image,settings);require(!working.isNull(),"Empty master");
        cv::Mat image;cv::cvtColor(working.linearRgba,image,cv::COLOR_RGBA2RGB);
        const auto start=std::chrono::steady_clock::now();const auto model=DetailProcessing::estimateNoise(image);
        const double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();
        require(model.valid,"Current single-image estimator unavailable");
        QJsonArray models,regions;QFile pixels(args[1]+".f32");
        require(pixels.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Cannot create single-frame crops");
        for(const auto &m:model.planes) models.append(QJsonObject{{"slope",m.slope},{"intercept",m.intercept},
            {"minimum_signal",m.minimumSignal},{"maximum_signal",m.maximumSignal},{"patches",m.patches},{"affine",m.affine}});
        for(const double fy:{.2,.5,.8}) for(const double fx:{.2,.5,.8}) {
            const cv::Rect r(int(std::lround(fx*image.cols))-128,int(std::lround(fy*image.rows))-128,256,256);
            require((r&cv::Rect(0,0,image.cols,image.rows))==r,"ROI outside image");
            std::array<cv::Mat,3> planes;for(auto &p:planes)p.create(256,256,CV_32F);
            for(int y=0;y<256;++y) {
                const auto *source=image.ptr<cv::Vec3f>(y+r.y)+r.x;
                for(int x=0;x<256;++x) {
                    planes[0].at<float>(y,x)=WorkingColor::luminance(source[x]);
                    planes[1].at<float>(y,x)=source[x][0]-source[x][2];
                    planes[2].at<float>(y,x)=source[x][1]-.5f*(source[x][0]+source[x][2]);
                }
            }
            const double mean=cv::mean(planes[0])[0];QJsonArray estimates,local;
            for(const auto &p:planes) {
                require(p.isContinuous() && cv::checkRange(p),"Invalid sample plane");
                const qint64 size=qint64(p.total()*p.elemSize());
                require(pixels.write(reinterpret_cast<const char *>(p.data),size)==size,"Incomplete sample plane");
            }
            for(int c=0;c<3;++c) {estimates.append(NoiseEstimation::sigma(model.planes[size_t(c)],float(mean)));local.append(NoiseEstimation::haarSigma(planes[size_t(c)]));}
            regions.append(QJsonObject{{"rect",QJsonArray{r.x,r.y,r.width,r.height}},{"mean_y",mean},
                {"predicted_effective_sigma",estimates},{"local_haar_mad_sigma",local}});
        }
        pixels.close();
        const QJsonObject result{{"raw",args[2]},{"sha256",TestRecipes::sha256(args[2])},{"models",models},
            {"regions",regions},{"estimate_ms",ms},{"width",image.cols},{"height",image.rows},
            {"declaration",TestRecipes::declaration(loaded,settings,args[2],"bruit","neutral",0.,args[2])},
            {"rules","One RAW only; existing fullframe production estimator, no burst/profile covariance imported; native grid fixed; no denoising or TIFF"}};
        QFile file(args[1]);require(file.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Cannot create output");
        const auto bytes=QJsonDocument(result).toJson(QJsonDocument::Compact);require(file.write(bytes)==bytes.size(),"Incomplete output");return 0;
    } catch(const std::exception &e) {std::cerr<<e.what()<<'\n';return 1;}
}
